<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { reportProvider } from '@/services/report'
import { ApiError } from '@/services/api'
import { useAuthStore } from '@/stores/auth'
import type { EnterprisePeriod, ReportView, ReportOptions, ReportForm, ReportListItem, ReportHistory } from '@/types/report'
import { emptyReport, normalizeReport, validateReport, formLabels, windowLabels, blockedLabels } from '@/utils/report'
import ReviewTimeline from '@/components/ReviewTimeline.vue'
import { reportStatusLabels } from '@/utils/review'
import { formatBeijingTime } from '@/utils/filing'
const route=useRoute();const auth=useAuthStore();const historyMode=computed(()=>route.path.endsWith('/history'));const periods=ref<EnterprisePeriod[]>([]);const options=ref<ReportOptions>({reductionTypes:[],reasons:[]});const view=ref<ReportView|null>(null);const form=reactive<ReportForm>(emptyReport());const code=ref('');const busy=ref(false);const errors=ref<Record<string,string>>({});const readonly=ref(false);const rows=ref<ReportListItem[]>([]);const total=ref(0);const page=ref(1);const status=ref('');const history=ref<ReportHistory|null>(null)
const reduced=computed(()=>form.baselineEmploymentCount!=null&&form.periodEmploymentCount!=null&&form.periodEmploymentCount<form.baselineEmploymentCount)
const reasonOptions=computed(()=>options.value.reasons.filter(r=>r.parentTypeCode===form.reductionTypeCode).flatMap(r=>[{code:r.code,name:r.name},...r.children.map(c=>({code:c.code,name:r.name+' / '+c.name}))]))
const editable=computed(()=>!readonly.value&&!view.value?.voided&&!!view.value?.canWrite)
const errorText=ref('')
async function attempt(fn:()=>Promise<void>){busy.value=true;errorText.value='';try{await fn()}catch(e){errorText.value=(e as Error).message;ElMessage.error(errorText.value);if(e instanceof ApiError){errors.value=e.fieldErrors;if(e.status===409&&code.value){await read(code.value,readonly.value);ElMessage.warning('状态或版本已变化，请重新确认最新数据')}}}finally{busy.value=false}}
async function list(){const r=await reportProvider.list({periodCode:code.value||undefined,status:status.value||undefined,page:page.value-1,size:20},auth.token!);rows.value=r.data.items;total.value=r.data.total}
async function read(c:string,ro=false){view.value=null;history.value=null;readonly.value=ro;code.value=c;errors.value={};if(!c)return;const r=(await reportProvider.get(c,auth.token!)).data;view.value=r;Object.assign(form,emptyReport(),r.form??{});if(r.baselineLocked)form.baselineEmploymentCount=r.lockedBaselineEmploymentCount;if(ro||r.submissionVersion>0)history.value=(await reportProvider.history(c,auth.token!)).data}
async function save(){const f=normalizeReport(form);errors.value=validateReport(f,options.value,false,view.value?.lockedBaselineEmploymentCount??null);if(Object.keys(errors.value).length)return;view.value=(await reportProvider.save(code.value,{...f,expectedVersion:view.value!.currentVersion},auth.token!)).data;Object.assign(form,view.value.form);ElMessage.success('草稿已保存，尚未上报')}
async function submit(){const f=normalizeReport(form);errors.value=validateReport(f,options.value,true,view.value?.lockedBaselineEmploymentCount??null);if(Object.keys(errors.value).length)return;try{await ElMessageBox.confirm('确认保存整份资料并提交至市级待审？审核中只读；正式退回后可修改重报。','确认提交',{type:'warning'})}catch{return}await attempt(async()=>{await save();await reportProvider.submit(code.value,view.value!.currentVersion,auth.token!);await read(code.value);periods.value=(await reportProvider.enterprisePeriods(auth.token!)).data.items;ElMessage.success('已提交，待市级审核')})}
function clearReasons(){for(const k of ['primaryReasonCode','primaryReasonDetail','secondaryReasonCode','secondaryReasonDetail','tertiaryReasonCode','tertiaryReasonDetail'] as const)form[k]=null}
onMounted(()=>attempt(async()=>{const [p,o]=await Promise.all([reportProvider.enterprisePeriods(auth.token!),reportProvider.options(auth.token!)]);periods.value=p.data.items;options.value=o.data;if(historyMode.value)await list()}))
watch(historyMode,()=>{view.value=null;code.value='';status.value='';page.value=1;errors.value={};if(historyMode.value)void attempt(list)})
</script>
<template><section><div class="page-heading"><div><h1>{{historyMode?'历史数据查询':'就业数据填报'}}</h1><p>北京时间显示；减员与建档期比较，提交后待市级审核。</p></div></div><el-alert v-if="errorText" :title="errorText" type="error" :closable="false"/><el-card v-loading="busy" shadow="never"><el-form inline><el-form-item label="调查期"><el-select v-model="code" clearable style="width: min(360px,70vw)" placeholder="请选择调查期" @change="historyMode?(view=null):attempt(()=>read(code))"><el-option v-for="p in periods" :key="p.code" :label="p.label+' · '+windowLabels[p.windowStatus]" :value="p.code"/></el-select></el-form-item><template v-if="historyMode"><el-form-item label="状态"><el-select v-model="status" clearable style="width:180px"><el-option v-for="(label,key) in reportStatusLabels" :key="key" :label="label" :value="key"/></el-select></el-form-item><el-button @click="page=1;attempt(list)">查询</el-button><el-button @click="code='';status='';page=1;view=null;attempt(list)">清除</el-button></template></el-form>
<template v-if="!historyMode&&!view"><el-empty description="请选择调查期；备案与开放状态由服务器判断"/><p v-for="p in periods" :key="p.code">{{p.label}}：{{p.blockedReason?blockedLabels[p.blockedReason]:'可填写'}}；窗口 {{formatBeijingTime(p.openAt)}} 至 {{formatBeijingTime(p.closeAt)}}</p></template>
<template v-if="historyMode"><el-table :data="rows" empty-text="暂无本企业历史记录"><el-table-column prop="periodLabel" label="调查期"/><el-table-column label="状态"><template #default="s">{{reportStatusLabels[s.row.status as keyof typeof reportStatusLabels]}}{{s.row.voided?'（已作废）':''}}</template></el-table-column><el-table-column prop="currentVersion" label="当前版本"/><el-table-column label="提交时间"><template #default="s">{{formatBeijingTime(s.row.submittedAt)}}</template></el-table-column><el-table-column label="操作"><template #default="s"><el-button @click="attempt(()=>read(s.row.periodCode,true))">只读详情</el-button><el-button v-if="s.row.status==='RETURNED_CITY'||s.row.status==='RETURNED_PROVINCE'" @click="attempt(()=>read(s.row.periodCode,false))">修改重报</el-button></template></el-table-column></el-table><el-pagination v-if="total" v-model:current-page="page" :page-size="20" :total="total" layout="total,prev,pager,next" @current-change="attempt(list)"/></template>
<template v-if="view"><el-alert v-if="view.voided" :title="'本报表已作废 · '+formatBeijingTime(view.voidedAt)+'；历史快照保留，只读'" type="warning" :closable="false"/><h2>{{view.periodCode}} · {{view.status?reportStatusLabels[view.status]:'未填报'}}</h2><el-alert v-if="view.latestReturn" :title="`${view.latestReturn.level==='CITY'?'市级':'省级'}退回 · ${view.latestReturn.comment||'未填写备注'} · ${formatBeijingTime(view.latestReturn.reviewedAt)}`" type="warning" :closable="false"/><p v-if="view.latestReturn">原报表退回后允许修改重报，重新提交仍须从市级审核开始。</p><el-alert :title="view.blockedReason?blockedLabels[view.blockedReason]:'可保存草稿或确认提交'" :type="view.canWrite?'info':'warning'" :closable="false"/><p>当前版本 {{view.currentVersion}} · 提交版本 {{view.submissionVersion}} · 提交时间 {{formatBeijingTime(view.submittedAt)}}</p><el-form label-position="top" :disabled="!editable"><div class="report-grid"><el-form-item v-for="key in (['baselineEmploymentCount','periodEmploymentCount'] as const)" :key="key" :label="formLabels[key]" :error="errors[key]" required><el-input-number v-model="form[key]" :min="0" :max="2147483647" :precision="0" :disabled="!editable||(key==='baselineEmploymentCount'&&view.baselineLocked)"/></el-form-item></div><p v-if="view.baselineLocked">建档期人数已在首次成功提交时锁定。</p><el-form-item :label="formLabels.otherReason" :error="errors.otherReason" required><el-input v-model="form.otherReason" type="textarea" maxlength="500" show-word-limit/></el-form-item><template v-if="reduced"><el-form-item :label="formLabels.reductionTypeCode" :error="errors.reductionTypeCode" required><el-select v-model="form.reductionTypeCode" clearable @change="clearReasons"><el-option v-for="o in options.reductionTypes" :key="o.code" :label="o.name" :value="o.code"/></el-select></el-form-item><template v-for="prefix in (['primary','secondary','tertiary'] as const)" :key="prefix"><el-form-item :label="formLabels[`${prefix}ReasonCode`]" :error="errors[`${prefix}ReasonCode`]" :required="prefix==='primary'"><el-select v-model="form[`${prefix}ReasonCode`]" clearable><el-option v-for="r in reasonOptions" :key="r.code" :label="r.name" :value="r.code"/></el-select></el-form-item><el-form-item :label="formLabels[`${prefix}ReasonDetail`]" :error="errors[`${prefix}ReasonDetail`]" :required="prefix==='primary'"><el-input v-model="form[`${prefix}ReasonDetail`]" type="textarea" maxlength="500" show-word-limit/></el-form-item></template></template><p v-else>人数未减少时，所有减少原因字段均以 null 保存。</p></el-form><div v-if="!readonly" class="form-actions"><el-button :disabled="!editable" :loading="busy" @click="attempt(save)">保存草稿</el-button><el-button type="primary" :disabled="!editable" :loading="busy" @click="submit">{{view.latestReturn?'修改并重新提交':'确认并提交'}}</el-button><el-button @click="attempt(()=>read(code))">重新读取</el-button></div><template v-if="history"><h3>审核时间线</h3><ReviewTimeline :events="history.reviewEvents??[]"/><h3>不可变提交快照</h3><el-empty v-if="!history.snapshots.length" description="草稿尚无提交快照"/><el-descriptions v-for="s in history.snapshots" :key="s.submissionVersion" :column="1" border><el-descriptions-item label="提交版本">{{s.submissionVersion}} · {{formatBeijingTime(s.submittedAt)}} · 提交人 {{s.submittedBy}}</el-descriptions-item><el-descriptions-item v-for="(label,k) in formLabels" :key="k" :label="label">{{s.form[k]??'—'}}</el-descriptions-item></el-descriptions></template></template></el-card></section></template>
<style scoped>.report-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:16px}.el-form{margin-top:20px}.el-select{width:100%}</style>
